inline std::string_view poolNoticeMessageKeyName(PoolNoticeMessageKey key){
    static constexpr std::array<std::string_view,poolNoticeMessageKeyCount> names={{"pool.notice.draft_changed","pool.notice.invalid_consent","pool.notice.invalid_remove","pool.notice.invalid_endpoint","pool.notice.saved","pool.notice.save_failed","pool.notice.at_most_eight","pool.notice.consent_revoked","pool.notice.cannot_remove","pool.notice.invalid_user_count"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage poolNoticeMessage(std::string_view language,PoolNoticeMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=poolNoticeMessageKeyCount)return {};
    const auto &source=poolNoticeLocalePacks()[0];const auto *selected=&source;for(const auto &pack:poolNoticeLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string poolNoticeEnglish(PoolNoticeMessageKey key){return std::string(poolNoticeMessage("en",key).text);}
